import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.CBWbbCW8.js";const _=JSON.parse('{"title":"计费与额度","description":"","frontmatter":{},"headers":[],"relativePath":"guide/billing-quota.md","filePath":"guide/billing-quota.md","lastUpdated":1784967005000}'),l={name:"guide/billing-quota.md"};function i(r,t,c,n,h,s){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="计费与额度" tabindex="-1">计费与额度 <a class="header-anchor" href="#计费与额度" aria-label="Permalink to &quot;计费与额度&quot;">​</a></h1><p>DouDi.ai 使用统一额度体系记录模型调用消耗。公开状态接口显示，当前站点开启了货币化展示，额度展示类型为 <code>USD</code>，默认额度换算单位为 <code>500000</code>，美元汇率字段为 <code>7.3</code>。这些值可能随平台设置调整，请以控制台和最新同步数据为准。</p><h2 id="额度如何理解" tabindex="-1">额度如何理解 <a class="header-anchor" href="#额度如何理解" aria-label="Permalink to &quot;额度如何理解&quot;">​</a></h2><p>平台公开数据中常见字段如下：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><code>quota_per_unit</code></td><td>额度单位换算基数。当前公开值为 <code>500000</code>。</td></tr><tr><td><code>quota_display_type</code></td><td>额度展示方式。当前公开值为 <code>USD</code>。</td></tr><tr><td><code>display_in_currency</code></td><td>是否按货币方式展示额度。当前公开值为 <code>true</code>。</td></tr><tr><td><code>usd_exchange_rate</code></td><td>美元汇率字段。当前公开值为 <code>7.3</code>。</td></tr><tr><td><code>model_ratio</code></td><td>模型输入计费权重。</td></tr><tr><td><code>completion_ratio</code></td><td>输出 token 相对输入 token 的计费倍数。</td></tr><tr><td><code>cache_ratio</code></td><td>缓存命中 token 的计费权重。</td></tr><tr><td><code>group_ratio</code></td><td>用户组或模型池的附加倍率。</td></tr></tbody></table><h2 id="消耗通常由哪些因素决定" tabindex="-1">消耗通常由哪些因素决定 <a class="header-anchor" href="#消耗通常由哪些因素决定" aria-label="Permalink to &quot;消耗通常由哪些因素决定&quot;">​</a></h2><p>一次请求的最终消耗通常会受到这些因素影响：</p><ul><li>选择的模型。</li><li>输入 token 数量。</li><li>输出 token 数量。</li><li>是否产生缓存读写。</li><li>当前账号所属用户组。</li><li>平台是否给某些模型配置了固定请求价格或特殊表达式计费。</li></ul><p>公开价格接口中的 <code>model_ratio</code>、<code>completion_ratio</code> 和 <code>group_ratio</code> 是理解费用的关键。实际扣费以登录后 <code>Usage Logs</code> 和 <code>Wallet</code> 中的记录为准。</p><h2 id="分组倍率" tabindex="-1">分组倍率 <a class="header-anchor" href="#分组倍率" aria-label="Permalink to &quot;分组倍率&quot;">​</a></h2><p>公开价格接口当前返回的分组示例：</p><table tabindex="0"><thead><tr><th>分组</th><th style="text-align:right;">倍率</th><th>说明</th></tr></thead><tbody><tr><td><code>Codex-Stable</code></td><td style="text-align:right;"><code>0.5</code></td><td>×20Pro池，核心生产</td></tr><tr><td><code>Codex-Standard</code></td><td style="text-align:right;"><code>0.2</code></td><td>Plus池，基础生产</td></tr><tr><td><code>Claude-MAX</code></td><td style="text-align:right;"><code>2.5</code></td><td>公开接口未返回说明</td></tr><tr><td><code>Claude-AWS</code></td><td style="text-align:right;"><code>3</code></td><td>公开接口未返回说明</td></tr></tbody></table><p>如果某个模型只对特定分组开放，你的账号必须拥有对应分组权限才能调用。</p><h2 id="查看自己的余额和消耗" tabindex="-1">查看自己的余额和消耗 <a class="header-anchor" href="#查看自己的余额和消耗" aria-label="Permalink to &quot;查看自己的余额和消耗&quot;">​</a></h2><ol><li>进入 <code>Wallet</code> 页面查看余额、充值和额度情况。</li><li>进入 <code>Usage Logs</code> 页面查看每次请求的模型、状态和消耗。</li><li>当发现消耗异常时，先检查是否使用了高倍率模型、长上下文输入或大量输出。</li></ol><h2 id="控制成本的建议" tabindex="-1">控制成本的建议 <a class="header-anchor" href="#控制成本的建议" aria-label="Permalink to &quot;控制成本的建议&quot;">​</a></h2><ul><li>日常测试优先选择低倍率模型。</li><li>长文本请求先压缩输入，减少不必要的上下文。</li><li>给测试 API Key 设置较低额度。</li><li>定期查看调用日志，及时发现异常请求。</li><li>在生产项目中记录请求 ID、模型名和业务场景，便于对账。</li></ul>',17)])])}const p=e(l,[["render",i]]);export{_ as __pageData,p as default};
